//! Clipboard history. macOS keeps no history of its own, so Mac Tools records
//! the general pasteboard while it runs: a background thread watches
//! `changeCount` and keeps the last 16 distinct copies **in memory only**
//! (never written to disk; gone when the plugin stops).
//!
//! Copies that apps mark private are skipped (the nspasteboard.org
//! `ConcealedType` / `TransientType` / `AutoGeneratedType` markers set by
//! password managers and similar tools). Picking an entry writes every
//! representation back (text, rich text, images, files…) and pastes with ⌘V.

use crate::icon;
use objc2::rc::{autoreleasepool, Retained};
use objc2::runtime::ProtocolObject;
use objc2_app_kit::{NSPasteboard, NSPasteboardItem, NSPasteboardWriting};
use objc2_foundation::{NSArray, NSData, NSString};
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Mutex;
use std::time::Duration;

const MAX_ITEMS: usize = 16;
/// Copies bigger than this (all representations) are not kept.
const MAX_BYTES: usize = 32 * 1024 * 1024;
const SKIP_MARKERS: [&str; 3] = ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType"];

/// One pasteboard item: every (type, bytes) representation it had.
type Item = Vec<(String, Vec<u8>)>;

#[derive(Clone)]
pub struct Entry {
    pub id: u64,
    pub label: String,
    /// Lucide name or a thumbnail data URI.
    pub icon: String,
    items: Vec<Item>,
}

static HISTORY: Mutex<Vec<Entry>> = Mutex::new(Vec::new());
static STARTED: AtomicBool = AtomicBool::new(false);

/// Start the watcher thread (once).
pub fn start() {
    if STARTED.swap(true, Ordering::SeqCst) {
        return;
    }
    std::thread::spawn(|| {
        let mut last = -1isize;
        loop {
            let count = autoreleasepool(|_| NSPasteboard::generalPasteboard().changeCount());
            if count != last {
                last = count;
                if let Some(e) = autoreleasepool(|_| capture()) {
                    let mut h = HISTORY.lock().unwrap();
                    h.retain(|x| x.id != e.id);
                    h.insert(0, e);
                    h.truncate(MAX_ITEMS);
                }
            }
            std::thread::sleep(Duration::from_millis(400));
        }
    });
}

pub fn list() -> Vec<Entry> {
    HISTORY.lock().unwrap().clone()
}

pub fn get(id: u64) -> Option<Entry> {
    HISTORY.lock().unwrap().iter().find(|e| e.id == id).cloned()
}

fn capture() -> Option<Entry> {
    let pb = NSPasteboard::generalPasteboard();
    let pitems = pb.pasteboardItems()?;
    let mut items: Vec<Item> = vec![];
    let mut total = 0usize;
    for it in pitems.iter() {
        let mut reps: Item = vec![];
        for ty in it.types().iter() {
            let t = ty.to_string();
            if SKIP_MARKERS.contains(&t.as_str()) {
                return None;
            }
            // Dynamic (promised) types are app-private and re-derived by the system.
            if t.starts_with("dyn.") {
                continue;
            }
            if let Some(data) = it.dataForType(&ty) {
                let bytes = data.to_vec();
                total += bytes.len();
                if total > MAX_BYTES {
                    return None;
                }
                reps.push((t, bytes));
            }
        }
        if !reps.is_empty() {
            items.push(reps);
        }
    }
    if items.is_empty() {
        return None;
    }
    let (label, icon) = describe(&items);
    let mut hasher = DefaultHasher::new();
    items.hash(&mut hasher);
    Some(Entry { id: hasher.finish(), label, icon, items })
}

fn rep<'a>(item: &'a Item, ty: &str) -> Option<&'a [u8]> {
    item.iter().find(|(t, _)| t == ty).map(|(_, b)| b.as_slice())
}

/// Wheel label + icon for a copy: its text, its file names, or an image thumbnail.
fn describe(items: &[Item]) -> (String, String) {
    let first = &items[0];
    let files: Vec<String> = items
        .iter()
        .filter_map(|i| rep(i, "public.file-url"))
        .filter_map(|b| std::str::from_utf8(b).ok())
        .map(|u| percent_decode(u.trim_end_matches('/').rsplit('/').next().unwrap_or(u)))
        .collect();
    if !files.is_empty() {
        let label = if files.len() == 1 { files[0].clone() } else { format!("{} (+{} more)", files[0], files.len() - 1) };
        return (label, "folder".into());
    }
    if let Some(text) = rep(first, "public.utf8-plain-text").and_then(|b| std::str::from_utf8(b).ok()) {
        let one_line = text.split_whitespace().collect::<Vec<_>>().join(" ");
        if !one_line.is_empty() {
            return (one_line.chars().take(60).collect(), "clipboard".into());
        }
    }
    for ty in ["public.png", "public.tiff", "public.jpeg", "public.heic"] {
        if let Some(bytes) = rep(first, ty) {
            return ("Image".into(), icon::thumbnail(bytes).unwrap_or_else(|| "image".into()));
        }
    }
    ("Clipboard item".into(), "clipboard".into())
}

fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() {
            if let Ok(v) = u8::from_str_radix(&s[i + 1..i + 3], 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// Put an entry back on the pasteboard, every representation of every item.
pub fn restore(e: &Entry) -> arclet_sdk::Result {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        let objs: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = e
            .items
            .iter()
            .map(|item| {
                let pi = NSPasteboardItem::new();
                for (ty, bytes) in item {
                    pi.setData_forType(&NSData::with_bytes(bytes), &NSString::from_str(ty));
                }
                ProtocolObject::from_retained(pi)
            })
            .collect();
        pb.clearContents();
        if pb.writeObjects(&NSArray::from_retained_slice(&objs)) {
            Ok(())
        } else {
            Err(arclet_sdk::Error::msg("Couldn't put that item back on the clipboard"))
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_file_names() {
        assert_eq!(percent_decode("My%20File%E2%9C%93.txt"), "My File✓.txt");
        assert_eq!(percent_decode("100%"), "100%");
    }

    #[test]
    fn describes_text_files_and_fallbacks() {
        let text = vec![vec![("public.utf8-plain-text".to_string(), b"  hello\n  world ".to_vec())]];
        assert_eq!(describe(&text).0, "hello world");
        let files = vec![
            vec![("public.file-url".to_string(), b"file:///Users/x/a%20b.txt".to_vec())],
            vec![("public.file-url".to_string(), b"file:///Users/x/dir/".to_vec())],
        ];
        assert_eq!(describe(&files), ("a b.txt (+1 more)".to_string(), "folder".to_string()));
    }
}
